package au.aumanet.app;
import android.util.AtomicFile;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;
/** Evidence of a possibly irreversible activation; never active consent or replay authority. */
final class NodeUpdateJournal {
 private final AtomicFile file;private boolean poisoned;private JSONObject record;
 NodeUpdateJournal(File file){this.file=new AtomicFile(file);if(file.exists()||new File(file.getPath()+".bak").exists())try{record=checked(GroupNameJson.object(new String(NodeUpdateCache.read(this.file.openRead(),4096),StandardCharsets.UTF_8),4096));}catch(Exception invalid){poisoned=true;}}
 synchronized boolean healthy(){return !poisoned;}synchronized JSONObject current(){try{return record==null?null:new JSONObject(record.toString());}catch(Exception invalid){throw new IllegalStateException("Update journal unavailable");}}
 /** An in-progress operation owns its journal; uncertainty starts after it retires. */
 synchronized boolean unresolved(String activeOperationId){return record!=null&&!record.optString("operationId","").equals(activeOperationId);}
 static JSONObject checked(JSONObject v)throws Exception{GatewayBindingConfig.keys(v,"schema","operationId","groupId","selfId","epoch","nodeId","originalRun","beforeSha256","releaseDigest","imageSha256","nodePin","configDigest","configRevision","activated");if(!"aumanet.node-update-operation.v1".equals(v.getString("schema"))||!GroupWire.id(v.getString("operationId"))||!GroupWire.id(v.getString("groupId"))||!GroupWire.pin(v.getString("selfId"))||GroupNameMetadata.number(v,"epoch")<1||!GroupWire.id(v.getString("nodeId"))||!GroupWire.id(v.getString("originalRun"))||!v.getString("beforeSha256").matches("[a-f0-9]{64}")||!v.getString("releaseDigest").matches("[a-f0-9]{64}")||!v.getString("imageSha256").matches("[a-f0-9]{64}")||!v.getString("nodePin").matches("[a-f0-9]{64}")||!v.getString("configDigest").matches("[A-F0-9]{64}")||GroupNameMetadata.number(v,"configRevision")<1||!(v.get("activated") instanceof Boolean))throw new IOException();return new JSONObject(v.toString());}
 synchronized void save(JSONObject raw)throws Exception{if(poisoned)throw new IOException();JSONObject value=checked(raw);byte[] bytes=value.toString().getBytes(StandardCharsets.UTF_8);FileOutputStream out=null;try{out=file.startWrite();out.write(bytes);file.finishWrite(out);out=null;if(!Arrays.equals(bytes,NodeUpdateCache.read(file.openRead(),4096)))throw new IOException();record=value;}catch(Exception failed){poisoned=true;if(out!=null)file.failWrite(out);throw new IOException("Update operation storage is unavailable");}}
 synchronized void clear()throws Exception{if(poisoned)throw new IOException();file.delete();if(file.getBaseFile().exists()){poisoned=true;throw new IOException();}record=null;}
}
